-- Encoded release
local d=table.concat({"","","","","","","","","","","","","","","","",""})
local a="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local t={};for i=1,#a do t[a:sub(i,i)]=i-1 end
local out,c={},{};local n,q=0,0
for i=1,#d do local v=t[d:sub(i,i)];if v then n=n*64+v;q=q+6;if q>=8 then q=q-8;c[#c+1]=string.char(math.floor(n/(2^q))%256);n=n%(2^q);if #c==4096 then out[#out+1]=table.concat(c);c={} end end end end
if #c>0 then out[#out+1]=table.concat(c) end
local f,e=loadstring(table.concat(out));assert(f,e);return f()
